package com.yihe.framework.ehr;
import java.util.*;import java.math.BigDecimal;import java.net.URI;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
@Service @SuppressWarnings("unchecked") public class AssessmentRuleService {
 final EhrRepository db;final EhrService ehr;static final Set<String>KINDS=new HashSet<>(Arrays.asList("reference","conversion","demographic","risk","occupational","questionnaire","prompt"));static final Set<String>MODULES=new HashSet<>(Arrays.asList("exam","comprehensive","chronic","occupational","psychological","questionnaire"));
 public AssessmentRuleService(EhrRepository db,EhrService ehr){this.db=db;this.ehr=ehr;}
 void doctor(EhrActor a){require(!a.mobile&&a.doctor,403,"评估规则管理仅供当前单位授权医生使用");}
 Object canonical(Object o){if(o instanceof Map){Map<String,Object>m=new TreeMap<>();((Map<?,?>)o).forEach((k,v)->m.put(String.valueOf(k),canonical(v)));return m;}if(o instanceof List){List<Object>l=new ArrayList<>();for(Object v:(List<?>)o)l.add(canonical(v));return l;}return o;}
 String hash(Object o){return hex(digest(bytes(ehr.encode(canonical(o)))));}
 String field(Map<String,Object>b,String k,int max,boolean required){String v=text(b,k);require((!required||!v.isEmpty())&&v.length()<=max,422,"请检查字段："+k);return v;}
 Map<String,Object> receipt(EhrActor a,String op,Map<String,Object>b){String key=text(b,"requestKey"),payload=hash(map("op",op,"body",b,"actor",a.user));require(key.matches("[0-9a-fA-F-]{36}"),422,"请求键无效");db.exec("INSERT IGNORE INTO a_assessment_rule_mutations(scope_code,data_mode,request_key,payload_digest,actor,created_at) VALUES(?,?,?,?,?,UTC_TIMESTAMP(6))",a.scope,a.mode,key,payload,a.user);Map<String,Object>r=db.one("SELECT * FROM a_assessment_rule_mutations WHERE scope_code=? AND data_mode=? AND request_key=? FOR UPDATE",a.scope,a.mode,key);require(payload.equals(r.get("payload_digest")),409,"请求键内容冲突");return r;}
 Object finish(EhrActor a,Map<String,Object>b,Object result){db.exec("UPDATE a_assessment_rule_mutations SET result_json=? WHERE scope_code=? AND data_mode=? AND request_key=?",ehr.encode(result),a.scope,a.mode,text(b,"requestKey"));return result;}
 Map<String,Object>owned(EhrActor a,String id,boolean lock){Map<String,Object>h=db.one("SELECT * FROM a_assessment_rule_heads WHERE rule_id=? AND scope_code=? AND data_mode=?"+(lock?" FOR UPDATE":""),id,a.scope,a.mode);require(h!=null,404,"规则不存在或无权限");return h;}
 Map<String,Object>version(EhrActor a,String id,int rev){Map<String,Object>r=db.one("SELECT * FROM a_assessment_rule_versions WHERE rule_id=? AND revision=? AND scope_code=? AND data_mode=?",id,rev,a.scope,a.mode);require(r!=null,404,"规则版本不存在");r.put("document",ehr.decode(r.remove("document_json")));return r;}
 void expected(Map<String,Object>h,Map<String,Object>b){Object v=b.get("version");require(v instanceof Number&&((Number)v).doubleValue()==num(h.get("row_version")),409,"规则已更新，请刷新后再操作");}
 BigDecimal decimal(Object x,boolean optional){if(x==null||x instanceof String&&str(x).trim().isEmpty()){require(optional,422,"缺少数值");return null;}require(x instanceof Number||x instanceof String,422,"数值格式无效");try{BigDecimal n=new BigDecimal(str(x));require(n.precision()<=20&&n.scale()<=8&&n.abs().compareTo(new BigDecimal("1000000000000"))<=0,422,"数值超出支持范围");return n;}catch(NumberFormatException e){throw new EhrException(422,"数值必须为有限十进制数");}}
 Map<String,Object>document(Map<String,Object>b){String kind=field(b,"kind",30,true),sex=text(b,"sex");require(KINDS.contains(kind)&&Arrays.asList("all","male","female").contains(sex),422,"规则类别或适用性别无效");Object modules=b.get("modules");require(modules instanceof List&&!((List<?>)modules).isEmpty()&&((List<?>)modules).size()<=6,422,"请选择适用评估模块");Set<String>seen=new HashSet<>();for(Object v:(List<?>)modules)require(v instanceof String&&MODULES.contains(v)&&seen.add(str(v)),422,"适用模块重复或无效");for(String k:Arrays.asList("ageMin","ageMax")){Object v=b.get(k);require(v==null||v instanceof Number&&((Number)v).doubleValue()==((Number)v).intValue()&&num(v)>=0&&num(v)<=150,422,"年龄范围应为0至150的整数或留空");}require(b.get("ageMin")==null||b.get("ageMax")==null||num(b.get("ageMin"))<=num(b.get("ageMax")),422,"年龄上下限顺序无效");Object priority=b.get("priority");require(priority instanceof Number&&((Number)priority).doubleValue()==num(priority)&&num(priority)>=0&&num(priority)<=1000,422,"优先级应为0至1000的整数");String url=field(b,"sourceUrl",2000,false);if(!url.isEmpty())try{URI u=URI.create(url);require(Arrays.asList("http","https").contains(u.getScheme())&&u.getHost()!=null&&u.getUserInfo()==null,422,"来源链接只支持有效http或https地址");}catch(IllegalArgumentException e){throw new EhrException(422,"来源链接格式无效");}
 Map<String,Object>d=map("kind",kind,"title",field(b,"title",150,true),"indicatorKey",field(b,"indicatorKey",100,true),"category",field(b,"category",100,true),"unit",field(b,"unit",60,false),"population",field(b,"population",255,true),"sex",sex,"ageMin",b.get("ageMin"),"ageMax",b.get("ageMax"),"priority",num(priority),"modules",new ArrayList<>(seen),"source",field(b,"source",2000,true),"sourceUrl",url,"sourceVersion",field(b,"sourceVersion",100,true),"notes",field(b,"notes",3000,false));
 if(Arrays.asList("reference","demographic").contains(kind)){require(!str(d.get("unit")).isEmpty(),422,"数值参考规则必须注明单位");BigDecimal low=decimal(b.get("lower"),true),high=decimal(b.get("upper"),true);require(low!=null||high!=null,422,"请至少填写一个参考边界");require(low==null||high==null||low.compareTo(high)<=0,422,"参考上下限顺序无效");require(b.get("lowerInclusive") instanceof Boolean&&b.get("upperInclusive") instanceof Boolean,422,"请明确边界是否包含");require(low==null||high==null||low.compareTo(high)!=0||Boolean.TRUE.equals(b.get("lowerInclusive"))&&Boolean.TRUE.equals(b.get("upperInclusive")),422,"相同边界必须同时包含，否则区间为空");d.putAll(map("lower",low,"upper",high,"lowerInclusive",b.get("lowerInclusive"),"upperInclusive",b.get("upperInclusive")));}
 if(kind.equals("conversion")){String to=field(b,"toUnit",60,true);require(!str(d.get("unit")).isEmpty()&&!to.equals(d.get("unit")),422,"请填写不同的来源与目标单位");BigDecimal factor=decimal(b.get("factor"),false),offset=decimal(b.get("offset"),false);require(factor.signum()>0,422,"换算系数必须为正数");d.putAll(map("toUnit",to,"factor",factor,"offset",offset));}
 if(kind.equals("risk")){require(!str(d.get("unit")).isEmpty(),422,"分层规则必须注明单位");Object raw=b.get("bands");require(raw instanceof List&&!((List<?>)raw).isEmpty()&&((List<?>)raw).size()<=20,422,"请填写1至20个分层区间");List<Object>bands=new ArrayList<>();for(Object v:(List<?>)raw){require(v instanceof Map,422,"分层格式无效");Map<String,Object>band=(Map<String,Object>)v;BigDecimal low=decimal(band.get("lower"),true),high=decimal(band.get("upper"),true);String level=text(band,"level");require(Arrays.asList("low","medium","high","critical").contains(level)&&(low!=null||high!=null)&&(low==null||high==null||low.compareTo(high)<=0)&&band.get("lowerInclusive") instanceof Boolean&&band.get("upperInclusive") instanceof Boolean,422,"分层等级或边界无效");require(low==null||high==null||low.compareTo(high)!=0||Boolean.TRUE.equals(band.get("lowerInclusive"))&&Boolean.TRUE.equals(band.get("upperInclusive")),422,"分层区间为空");bands.add(map("label",field(band,"label",150,true),"level",level,"lower",low,"upper",high,"lowerInclusive",band.get("lowerInclusive"),"upperInclusive",band.get("upperInclusive")));}for(int i=0;i<bands.size();i++)for(int j=i+1;j<bands.size();j++)require(!overlap((Map<String,Object>)bands.get(i),(Map<String,Object>)bands.get(j)),422,"分层区间存在重叠，请明确边界包含关系");d.put("bands",bands);}
 if(kind.equals("occupational")){Object words=b.get("keywords");require(words instanceof List&&!((List<?>)words).isEmpty()&&((List<?>)words).size()<=30,422,"请填写1至30个接触关键词");List<String>keys=new ArrayList<>();for(Object w:(List<?>)words)require(w instanceof String&&!str(w).trim().isEmpty()&&str(w).length()<=60&&keys.add(str(w).trim()),422,"关键词格式无效");d.put("keywords",keys);d.put("text",field(b,"text",4000,true));}
 if(kind.equals("questionnaire")){require("choice_sum_v1".equals(b.get("method"))&&Boolean.TRUE.equals(b.get("reviewRequired")),422,"当前仅支持配置选项分值汇总，且必须保留专业审核");d.putAll(map("method","choice_sum_v1","reviewRequired",true,"text",field(b,"text",4000,true)));}
 if(kind.equals("prompt"))d.put("text",field(b,"text",4000,true));require(ehr.encode(d).length()<=30000,422,"规则内容过大");return d;}
 boolean overlap(Map<String,Object>a,Map<String,Object>b){BigDecimal al=decimal(a.get("lower"),true),au=decimal(a.get("upper"),true),bl=decimal(b.get("lower"),true),bu=decimal(b.get("upper"),true);if(au!=null&&bl!=null&&(au.compareTo(bl)<0||au.compareTo(bl)==0&&!(Boolean.TRUE.equals(a.get("upperInclusive"))&&Boolean.TRUE.equals(b.get("lowerInclusive")))))return false;if(bu!=null&&al!=null&&(bu.compareTo(al)<0||bu.compareTo(al)==0&&!(Boolean.TRUE.equals(b.get("upperInclusive"))&&Boolean.TRUE.equals(a.get("lowerInclusive")))))return false;return true;}
 void event(EhrActor a,String id,int rev,String action,String reason){db.insert("a_assessment_rule_events",map("event_id",id(),"rule_id",id,"scope_code",a.scope,"data_mode",a.mode,"revision",rev,"action",action,"actor",a.user,"reason",reason,"created_at",now()));ehr.audit(a,null,null,null,"assessment_rule_"+action,"规则 "+id+" V"+rev+"；"+reason);}
 Object draft(EhrActor a,String id,Map<String,Object>doc,String reason){int rev=1;if(id==null){id=id();db.insert("a_assessment_rule_heads",map("rule_id",id,"scope_code",a.scope,"data_mode",a.mode,"rule_kind",doc.get("kind"),"title",doc.get("title"),"indicator_key",doc.get("indicatorKey"),"category",doc.get("category"),"draft_revision",1,"created_by",a.user,"updated_by",a.user,"created_at",now(),"updated_at",now()));}else{rev=(int)db.count("SELECT COALESCE(MAX(revision),0)+1 FROM a_assessment_rule_versions WHERE rule_id=?",id);db.exec("UPDATE a_assessment_rule_heads SET title=IF(active_revision IS NULL,?,title),indicator_key=IF(active_revision IS NULL,?,indicator_key),category=IF(active_revision IS NULL,?,category),draft_revision=?,row_version=row_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE rule_id=?",doc.get("title"),doc.get("indicatorKey"),doc.get("category"),rev,a.user,id);}db.insert("a_assessment_rule_versions",map("rule_id",id,"revision",rev,"scope_code",a.scope,"data_mode",a.mode,"document_json",ehr.encode(doc),"created_by",a.user,"created_at",now()));event(a,id,rev,"draft",reason);return map("id",id,"revision",rev);}
 @Transactional public Object save(EhrActor a,Map<String,Object>b){doctor(a);Map<String,Object>r=receipt(a,"save",b);if(r.get("result_json")!=null)return ehr.decode(r.get("result_json"));Map<String,Object>d=document(b);String id=text(b,"id");if(!id.isEmpty()){Map<String,Object>h=owned(a,id,true);expected(h,b);require(d.get("kind").equals(h.get("rule_kind")),422,"既有规则不能变更类别，请新建规则");}return finish(a,b,draft(a,id.isEmpty()?null:id,d,field(b,"reason",1500,true)));}
 void conflict(EhrActor a,String id,Map<String,Object>d){for(Map<String,Object>r:db.all("SELECT h.rule_id id,v.document_json document FROM a_assessment_rule_heads h JOIN a_assessment_rule_versions v ON v.rule_id=h.rule_id AND v.revision=h.active_revision AND v.scope_code=h.scope_code AND v.data_mode=h.data_mode WHERE h.scope_code=? AND h.data_mode=? AND h.enabled=1",a.scope,a.mode)){if(id.equals(r.get("id")))continue;Map<String,Object>x=(Map<String,Object>)ehr.decode(r.get("document"));boolean sameKind=d.get("kind").equals(x.get("kind"))||Arrays.asList("reference","demographic").contains(d.get("kind"))&&Arrays.asList("reference","demographic").contains(x.get("kind"));if(!sameKind||!str(d.get("indicatorKey")).equalsIgnoreCase(str(x.get("indicatorKey")))||!str(d.get("unit")).equals(str(x.get("unit")))||num(d.get("priority"))!=num(x.get("priority"))||Collections.disjoint((List<?>)d.get("modules"),(List<?>)x.get("modules")))continue;if(d.get("kind").equals("conversion")&&!d.get("toUnit").equals(x.get("toUnit")))continue;String sex=str(d.get("sex")),sx=str(x.get("sex"));int lo=d.get("ageMin")==null?0:num(d.get("ageMin")),hi=d.get("ageMax")==null?150:num(d.get("ageMax")),xl=x.get("ageMin")==null?0:num(x.get("ageMin")),xh=x.get("ageMax")==null?150:num(x.get("ageMax"));require(!(sex.equals("all")||sx.equals("all")||sex.equals(sx))||hi<xl||xh<lo,409,"同指标、单位、模块及优先级存在重叠的生效人群规则，请调整适用范围或优先级");}}
 @Transactional public Object action(EhrActor a,String id,Map<String,Object>b){doctor(a);String action=text(b,"action");require(Arrays.asList("publish","disable","enable","copy","restore").contains(action),422,"规则操作无效");Map<String,Object>r=receipt(a,action+id,b);if(r.get("result_json")!=null)return ehr.decode(r.get("result_json"));db.exec("INSERT IGNORE INTO a_assessment_rule_locks(scope_code,data_mode) VALUES(?,?)",a.scope,a.mode);db.one("SELECT guard FROM a_assessment_rule_locks WHERE scope_code=? AND data_mode=? FOR UPDATE",a.scope,a.mode);Map<String,Object>h=owned(a,id,true);expected(h,b);String reason=field(b,"reason",1500,true);int rev=h.get("active_revision")==null?num(h.get("draft_revision")):num(h.get("active_revision"));if(action.equals("copy")){if(b.get("revision") instanceof Number)rev=num(b.get("revision"));Map<String,Object>d=new LinkedHashMap<>((Map<String,Object>)version(a,id,rev).get("document"));String title=str(d.get("title"));d.put("title",title.substring(0,Math.min(140,title.length()))+"（副本）");d.put("copiedFrom",id);d.put("copiedRevision",rev);return finish(a,b,draft(a,null,d,reason));}if(action.equals("restore")){require(b.get("revision") instanceof Number,422,"请选择历史已发布版本");Map<String,Object>old=version(a,id,num(b.get("revision")));require(old.get("published_at")!=null,422,"只能将历史已发布版本恢复为新草稿");Map<String,Object>d=new LinkedHashMap<>((Map<String,Object>)old.get("document"));d.put("restoredFromRevision",num(b.get("revision")));return finish(a,b,draft(a,id,d,reason));}
 if(action.equals("publish")){require(h.get("draft_revision")!=null&&b.get("revision") instanceof Number&&num(b.get("revision"))==num(h.get("draft_revision")),409,"请发布当前待核对草稿版本");require(Boolean.TRUE.equals(b.get("sourceVerified")),422,"发布前必须核对来源、适用范围及边界");rev=num(h.get("draft_revision"));Map<String,Object>d=(Map<String,Object>)version(a,id,rev).get("document");conflict(a,id,d);for(Object module:(List<?>)d.get("modules")){int others=0;for(Map<String,Object>x:new AssessmentRuleRuntime(db,ehr).context(a,str(module)))if(!id.equals(x.get("id")))others++;require(others<500,422,"适用模块生效规则已达500条，请先整理");}db.exec("UPDATE a_assessment_rule_versions SET published_by=?,published_at=UTC_TIMESTAMP(6),publication_note=? WHERE rule_id=? AND revision=? AND published_at IS NULL",a.user,reason,id,rev);db.exec("UPDATE a_assessment_rule_heads SET active_revision=?,draft_revision=NULL,enabled=1,title=?,indicator_key=?,category=?,row_version=row_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE rule_id=?",rev,d.get("title"),d.get("indicatorKey"),d.get("category"),a.user,id);}else{require(h.get("active_revision")!=null,422,"规则尚无已发布版本");if(action.equals("enable")){require(Boolean.TRUE.equals(b.get("sourceVerified")),422,"启用前请核对来源与适用范围");Map<String,Object>d=(Map<String,Object>)version(a,id,rev).get("document");conflict(a,id,d);for(Object module:(List<?>)d.get("modules")){int others=0;for(Map<String,Object>x:new AssessmentRuleRuntime(db,ehr).context(a,str(module)))if(!id.equals(x.get("id")))others++;require(others<500,422,"适用模块生效规则已达500条，请先整理");}}db.exec("UPDATE a_assessment_rule_heads SET enabled=?,row_version=row_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE rule_id=?",action.equals("enable")?1:0,a.user,id);}event(a,id,rev,action,reason);return finish(a,b,map("id",id,"revision",rev,"action",action));}
 @Transactional public Object importRules(EhrActor a,Map<String,Object>b){doctor(a);Map<String,Object>r=receipt(a,"import",b);if(r.get("result_json")!=null)return ehr.decode(r.get("result_json"));Object raw=b.get("items");require(raw instanceof List&&!((List<?>)raw).isEmpty()&&((List<?>)raw).size()<=100,422,"每批导入1至100条规则");String reason=field(b,"reason",1500,true);List<Map<String,Object>>docs=new ArrayList<>();for(Object v:(List<?>)raw){require(v instanceof Map,422,"导入条目格式无效");docs.add(document((Map<String,Object>)v));}List<Object>ids=new ArrayList<>();for(Map<String,Object>d:docs)ids.add(draft(a,null,d,reason));return finish(a,b,map("drafts",ids,"count",ids.size()));}
 public Map<String,Object>detail(EhrActor a,String id,Integer revision){doctor(a);Map<String,Object>h=owned(a,id,false);int rev=revision==null?(h.get("active_revision")!=null?num(h.get("active_revision")):num(h.get("draft_revision"))):revision;Map<String,Object>v=version(a,id,rev);return map("head",h,"selected",v,"history",db.all("SELECT revision,created_by createdBy,created_at createdAt,published_by publishedBy,published_at publishedAt,publication_note note FROM a_assessment_rule_versions WHERE rule_id=? AND scope_code=? AND data_mode=? ORDER BY revision DESC",id,a.scope,a.mode),"events",db.all("SELECT revision,action,actor,reason,created_at time FROM a_assessment_rule_events WHERE rule_id=? AND scope_code=? AND data_mode=? ORDER BY created_at DESC,event_id DESC LIMIT 100",id,a.scope,a.mode));}
 public Map<String,Object>list(EhrActor a,Map<String,String>q){doctor(a);String kind=q.getOrDefault("kind","reference"),status=q.getOrDefault("status","active");require(KINDS.contains(kind)||kind.equals("versions"),422,"规则类别无效");require(Arrays.asList("","active","draft","disabled").contains(status),422,"规则状态无效");String base=" FROM a_assessment_rule_heads h JOIN a_assessment_rule_versions v ON v.rule_id=h.rule_id AND v.revision="+(status.equals("draft")?"h.draft_revision":"COALESCE(h.active_revision,h.draft_revision)")+" AND v.scope_code=h.scope_code AND v.data_mode=h.data_mode WHERE h.scope_code=? AND h.data_mode=?",where=base;List<Object>args=new ArrayList<>(Arrays.asList(a.scope,a.mode));if(!kind.equals("versions")){where+=" AND h.rule_kind=?";args.add(kind);}if(status.equals("active"))where+=" AND h.enabled=1 AND h.active_revision IS NOT NULL";if(status.equals("draft"))where+=" AND h.draft_revision IS NOT NULL";if(status.equals("disabled"))where+=" AND h.enabled=0 AND h.active_revision IS NOT NULL";String search=q.getOrDefault("search","").trim();if(!search.isEmpty()){where+=" AND (JSON_UNQUOTE(JSON_EXTRACT(v.document_json,'$.title')) LIKE ? ESCAPE '!' OR JSON_UNQUOTE(JSON_EXTRACT(v.document_json,'$.indicatorKey')) LIKE ? ESCAPE '!')";args.add("%"+like(search)+"%");args.add("%"+like(search)+"%");}for(String k:Arrays.asList("population","category")){String value=q.getOrDefault(k,"");if(!value.isEmpty()){where+=k.equals("category")?" AND JSON_UNQUOTE(JSON_EXTRACT(v.document_json,'$.category'))=?":" AND JSON_UNQUOTE(JSON_EXTRACT(v.document_json,'$.population'))=?";args.add(value);}}int page=bounded(q.get("page"),1,1,100000),limit=bounded(q.get("limit"),10,1,100);long total=db.count("SELECT COUNT(*)"+where,args.toArray());args.add(limit);args.add((page-1)*limit);List<Map<String,Object>>items=db.all("SELECT h.*,v.revision displayedRevision,v.document_json document,v.published_at publishedAt"+where+" ORDER BY h.updated_at DESC,h.rule_id LIMIT ? OFFSET ?",args.toArray());for(Map<String,Object>h:items)h.put("document",ehr.decode(h.get("document")));Map<String,Object>counts=db.one("SELECT COUNT(*) total,SUM(enabled=1 AND active_revision IS NOT NULL) active,SUM(draft_revision IS NOT NULL) draft,SUM(enabled=0 AND active_revision IS NOT NULL) disabled FROM a_assessment_rule_heads WHERE scope_code=? AND data_mode=?",a.scope,a.mode);counts.put("versions",db.count("SELECT COUNT(*) FROM a_assessment_rule_versions WHERE scope_code=? AND data_mode=? AND published_at IS NOT NULL",a.scope,a.mode));counts.put("recent",db.count("SELECT COUNT(*) FROM a_assessment_rule_events WHERE scope_code=? AND data_mode=? AND created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)",a.scope,a.mode));return map("items",items,"total",total,"page",page,"limit",limit,"counts",counts,"options",db.all("SELECT DISTINCT JSON_UNQUOTE(JSON_EXTRACT(v.document_json,'$.category')) category,JSON_UNQUOTE(JSON_EXTRACT(v.document_json,'$.population')) population"+base+" ORDER BY category",a.scope,a.mode),"kind",kind);}
 public Object simulate(EhrActor a,Map<String,Object>b){doctor(a);String id=text(b,"id");Map<String,Object>h=owned(a,id,false);int rev=b.get("revision") instanceof Number?num(b.get("revision")):num(h.get("active_revision")!=null?h.get("active_revision"):h.get("draft_revision"));Map<String,Object>v=version(a,id,rev),d=(Map<String,Object>)v.get("document");Map<String,Object>out=map("ruleId",id,"revision",rev,"trialOnly",true,"writesHealthData",false,"published",v.get("published_at")!=null,"enabled",num(h.get("enabled"))==1);String sex=str(d.get("sex"));if(!sex.equals("all")&&!sex.equals(text(b,"sex"))){out.put("applied",false);out.put("reason","性别不匹配或未提供，不推测适用人群");return out;}if(d.get("ageMin")!=null||d.get("ageMax")!=null){Object age=b.get("age");if(!(age instanceof Number)||((Number)age).doubleValue()!=num(age)||num(age)<0||num(age)>150||(d.get("ageMin")!=null&&num(age)<num(d.get("ageMin")))||(d.get("ageMax")!=null&&num(age)>num(d.get("ageMax")))){out.put("applied",false);out.put("reason","年龄不匹配或未提供");return out;}}String kind=str(d.get("kind"));if(Arrays.asList("reference","demographic","conversion","risk").contains(kind)){if(!str(d.get("unit")).equals(text(b,"unit"))){out.put("applied",false);out.put("reason","单位不一致，不自动换算或套用参考范围");return out;}BigDecimal value=decimal(b.get("value"),false);out.put("input",value);if(kind.equals("conversion"))out.putAll(map("convertedValue",value.multiply(decimal(d.get("factor"),false)).add(decimal(d.get("offset"),false)),"toUnit",d.get("toUnit")));else if(kind.equals("risk")){Map<String,Object>matched=null;for(Object band:(List<?>)d.get("bands"))if(within(value,(Map<String,Object>)band))matched=(Map<String,Object>)band;out.put("matchedBand",matched);out.put("note","仅为配置区间试算，不是职工实际风险评估或诊断");}else out.put("referenceStatus",within(value,d)?"within":"outside");}else if(kind.equals("occupational")){String input=field(b,"text",10000,false).toLowerCase(Locale.ROOT);List<Object>matched=new ArrayList<>();for(Object word:(List<?>)d.get("keywords"))if(input.contains(str(word).toLowerCase(Locale.ROOT)))matched.add(word);out.put("matchedKeywords",matched);out.put("note","仅为接触记录关键词匹配，不等于已测定暴露剂量");}else if(kind.equals("questionnaire")){Object raw=b.get("scores");require(raw instanceof List&&((List<?>)raw).size()<=2000,422,"请提供不超过2000项配置分值");BigDecimal sum=BigDecimal.ZERO;for(Object x:(List<?>)raw){BigDecimal n=decimal(x,false);require(n.signum()>=0&&n.compareTo(new BigDecimal("100"))<=0,422,"单项配置分值应为0至100");sum=sum.add(n);}out.put("configuredScore",sum);}else out.put("prompt",d.get("text"));out.put("applied",true);return out;}
 boolean within(BigDecimal value,Map<String,Object>d){BigDecimal low=decimal(d.get("lower"),true),high=decimal(d.get("upper"),true);return (low==null||value.compareTo(low)>0||value.compareTo(low)==0&&Boolean.TRUE.equals(d.get("lowerInclusive")))&&(high==null||value.compareTo(high)<0||value.compareTo(high)==0&&Boolean.TRUE.equals(d.get("upperInclusive")));}
}
